---@class PopUpGiftView : ViewBase
PopUpGiftView = class("PopUpGiftView", ViewBase)
function PopUpGiftView:initialize()
    ViewBase.initialize(self)
    ViewBase.RegisteAction(self, "PopUpGiftViewAction")
end
function PopUpGiftView:Awake()
    CommonHelper:HButtonSetCallback("BtnClose", self.gameObject, function()
        UIManager:Get():ClosePopup()
    end)
    ---@type table<number,Page_PopUpGiftViewBase>
    self.pageView = {}
    for _, type in pairs(PopUpGiftType) do
        self.pageView[type] = Page_PopUpGiftViewBase.CreatePageGiftView(type, self.gameObject)
    end
    self.LeftBtn = CommonHelper:HButtonSetCallback("LeftBtn", self.gameObject, function()
        self:OnChangePageView(-1)
    end)
    self.RightBtn = CommonHelper:HButtonSetCallback("RightBtn", self.gameObject, function()
        self:OnChangePageView(1)
    end)
end

function PopUpGiftView:OnOpen()
    self.index = 1
    self:OnChangePageView(0)
end

function PopUpGiftView:RefreshView()
    self.index = 1
    self:OnChangePageView(0)
end

function PopUpGiftView:OnChangePageView(value)
    self.index = self.index + value
    ---@type table<number,PopUpGiftData>
    self.dataTable = PopUpGiftDataManager:Get():GetActivePopUpGiftDataList()
    if #self.dataTable>0 then
        local data = self.dataTable[self.index]
        if self.page then
            self.page:Close()
        end
        self.page = self.pageView[data:GetType()]
        if self.page then
            self.page:Open(data)
        else
            logError(" 弹出分页或弹出礼包数据为空，请检查 ")
        end
        self:UpdateBtnActive()
    else
        UIManager:Get():ClosePopup()
    end
end

function PopUpGiftView:UpdateBtnActive()
    CommonHelper:SetHButtonClick(self.LeftBtn, self.index > 1, true)
    CommonHelper:SetHButtonClick(self.RightBtn, self.index < #self.dataTable, true)
end
---@param delayData PopUpGiftData
function PopUpGiftView:SetPageView()
    self.dataTable = PopUpGiftDataManager:Get():GetActivePopUpGiftDataList()
    local delayData = PopUpGiftDataManager:Get():DelayData()
    for i, data in pairs(self.dataTable) do
        if data:GetConfig().C_ID == delayData:GetConfig().C_ID then
            self:OnChangePageView(i - self.index)
            CommonHelper:SetHButtonClick(self.LeftBtn, false, true)
            CommonHelper:SetHButtonClick(self.RightBtn, false, true)
            break
        end
    end
end

function PopUpGiftView:OnClose()
    if self.page then
        self.page:Close()
    end
    self.page=nil
    CommonHelper:ReleasePool(UIModuleID.PopUpGift)
end
